import re
import sys


class ExprError(Exception):
    def __init__(self, kind, pos):
        super().__init__("%s error at %d" % (kind, pos))
        self.kind = kind
        self.pos = pos


# --------------------------------------------------------------------------
# Tokenizer
# --------------------------------------------------------------------------

_TOKEN_RE = re.compile(
    r'[ \t\n]+'
    r'|([0-9]+)'
    r'|([A-Za-z_][A-Za-z0-9_]*)'
    r'|(\*\*|\|\||&&|==|!=|<=|>=|[-+*/%<>!?:(),])'
)


def _to_int(text):
    try:
        return int(text)
    except ValueError:            # very long literal on Python >= 3.11
        n = 0
        for k in range(0, len(text), 4000):
            chunk = text[k:k + 4000]
            n = n * (10 ** len(chunk)) + int(chunk)
        return n


def _tokenize(src):
    """Returns a list of (kind, value, pos).  Stops at the first illegal
    character / bad literal with an ('error', None, pos) token (no eof then)."""
    toks = []
    i = 0
    n = len(src)
    match = _TOKEN_RE.match
    while i < n:
        mo = match(src, i)
        if mo is None:
            toks.append(('error', None, i))
            return toks
        g = mo.lastindex
        if g is None:                       # whitespace
            i = mo.end()
            continue
        text = mo.group()
        if g == 1:
            if len(text) > 1 and text[0] == '0':
                toks.append(('error', None, i))
                return toks
            toks.append(('int', _to_int(text), i))
        elif g == 2:
            if text == 'true':
                toks.append(('true', None, i))
            elif text == 'false':
                toks.append(('false', None, i))
            else:
                toks.append(('ident', text, i))
        else:
            toks.append((text, None, i))
        i = mo.end()
    toks.append(('eof', None, n))
    return toks


# --------------------------------------------------------------------------
# Parser (precedence climbing, chains flattened to keep recursion shallow)
#
# AST nodes:
#   ('int', value)
#   ('bool', value)
#   ('var', name, pos)
#   ('call', name, pos, [args])
#   ('chain', level, first, [(op, pos, operand), ...])   left-assoc levels
#   ('bin', op, pos, left, right)                          non-assoc levels
#   ('pow', [(unary_ops, primary), ...], [powpos, ...])   unary / ** level
#   ('tern', [(cond, qpos, then), ...], final_else)
# --------------------------------------------------------------------------

_BIN_LEVELS = {
    '||': 2,
    '&&': 3,
    '==': 4, '!=': 4,
    '<': 5, '<=': 5, '>': 5, '>=': 5,
    '+': 6, '-': 6,
    '*': 7, '/': 7, '%': 7,
}
_NON_ASSOC = (4, 5)


class _Parser(object):
    def __init__(self, toks):
        self.toks = toks
        self.i = 0

    def _error(self):
        raise ExprError('syntax', self.toks[self.i][2])

    def parse(self):
        node = self.parse_ternary()
        if self.toks[self.i][0] != 'eof':
            self._error()
        return node

    def parse_ternary(self):
        cond = self.parse_binary(2)
        if self.toks[self.i][0] != '?':
            return cond
        parts = []
        while True:
            qpos = self.toks[self.i][2]
            self.i += 1                              # '?'
            a = self.parse_ternary()
            if self.toks[self.i][0] != ':':
                self._error()
            self.i += 1                              # ':'
            c = self.parse_binary(2)
            parts.append((cond, qpos, a))
            if self.toks[self.i][0] != '?':
                return ('tern', parts, c)
            cond = c

    def parse_binary(self, minlevel):
        left = self.parse_unary()
        last_level = 0
        toks = self.toks
        while True:
            tok = toks[self.i]
            level = _BIN_LEVELS.get(tok[0])
            if level is None or level < minlevel:
                return left
            op = tok[0]
            pos = tok[2]
            if level == last_level:
                if level in _NON_ASSOC:
                    raise ExprError('syntax', pos)
                self.i += 1
                right = self.parse_binary(level + 1)
                left[3].append((op, pos, right))
            else:
                self.i += 1
                right = self.parse_binary(level + 1)
                if level in _NON_ASSOC:
                    left = ('bin', op, pos, left, right)
                else:
                    left = ('chain', level, left, [(op, pos, right)])
                last_level = level

    def _collect_unary(self):
        ops = []
        toks = self.toks
        while True:
            tok = toks[self.i]
            if tok[0] == '-' or tok[0] == '!':
                ops.append((tok[0], tok[2]))
                self.i += 1
            else:
                return ops

    def parse_unary(self):
        ops = self._collect_unary()
        prim = self.parse_primary()
        if not ops and self.toks[self.i][0] != '**':
            return prim
        items = [(ops, prim)]
        powpos = []
        while self.toks[self.i][0] == '**':
            powpos.append(self.toks[self.i][2])
            self.i += 1
            ops = self._collect_unary()
            prim = self.parse_primary()
            items.append((ops, prim))
        return ('pow', items, powpos)

    def parse_primary(self):
        tok = self.toks[self.i]
        kind = tok[0]
        if kind == 'int':
            self.i += 1
            return ('int', tok[1])
        if kind == 'true':
            self.i += 1
            return ('bool', True)
        if kind == 'false':
            self.i += 1
            return ('bool', False)
        if kind == 'ident':
            self.i += 1
            name = tok[1]
            pos = tok[2]
            if self.toks[self.i][0] == '(':
                self.i += 1
                args = []
                if self.toks[self.i][0] != ')':
                    while True:
                        args.append(self.parse_ternary())
                        k = self.toks[self.i][0]
                        if k == ',':
                            self.i += 1
                        elif k == ')':
                            break
                        else:
                            self._error()
                self.i += 1                          # ')'
                return ('call', name, pos, args)
            return ('var', name, pos)
        if kind == '(':
            self.i += 1
            node = self.parse_ternary()
            if self.toks[self.i][0] != ')':
                self._error()
            self.i += 1
            return node
        self._error()


# --------------------------------------------------------------------------
# Evaluator
# --------------------------------------------------------------------------

def _is_int(v):
    return isinstance(v, int) and not isinstance(v, bool)


def _is_bool(v):
    return isinstance(v, bool)


def _arith(op, a, b, pos):
    if not (_is_int(a) and _is_int(b)):
        raise ExprError('type', pos)
    if op == '+':
        return a + b
    if op == '-':
        return a - b
    if op == '*':
        return a * b
    if op == '/' or op == '%':
        if b == 0:
            raise ExprError('zero-division', pos)
        q = abs(a) // abs(b)
        if (a < 0) != (b < 0):
            q = -q
        if op == '/':
            return q
        return a - q * b
    # '**'
    if b < 0 or b > 1000:
        raise ExprError('domain', pos)
    return a ** b


def _apply_unary(ops, v):
    for op, pos in reversed(ops):
        if op == '-':
            if not _is_int(v):
                raise ExprError('type', pos)
            v = -v
        else:  # '!'
            if not _is_bool(v):
                raise ExprError('type', pos)
            v = not v
    return v


def _make_evaluator(env):
    def ev(node):
        tag = node[0]
        if tag == 'int' or tag == 'bool':
            return node[1]

        if tag == 'var':
            name = node[1]
            if name not in env:
                raise ExprError('name', node[2])
            return env[name]

        if tag == 'chain':
            level = node[1]
            v = ev(node[2])
            if level == 2 or level == 3:
                for op, pos, operand in node[3]:
                    if not _is_bool(v):
                        raise ExprError('type', pos)
                    if op == '&&':
                        if v:
                            v = ev(operand)
                            if not _is_bool(v):
                                raise ExprError('type', pos)
                    else:  # '||'
                        if not v:
                            v = ev(operand)
                            if not _is_bool(v):
                                raise ExprError('type', pos)
                return v
            for op, pos, operand in node[3]:
                r = ev(operand)
                v = _arith(op, v, r, pos)
            return v

        if tag == 'bin':
            op = node[1]
            pos = node[2]
            l = ev(node[3])
            r = ev(node[4])
            if op == '==' or op == '!=':
                if not ((_is_int(l) and _is_int(r)) or (_is_bool(l) and _is_bool(r))):
                    raise ExprError('type', pos)
                return (l == r) if op == '==' else (l != r)
            if not (_is_int(l) and _is_int(r)):
                raise ExprError('type', pos)
            if op == '<':
                return l < r
            if op == '<=':
                return l <= r
            if op == '>':
                return l > r
            return l >= r

        if tag == 'pow':
            items = node[1]
            powpos = node[2]
            vals = [ev(prim) for _ops, prim in items]
            n = len(items)
            v = _apply_unary(items[n - 1][0], vals[n - 1])
            for i in range(n - 2, -1, -1):
                v = _arith('**', vals[i], v, powpos[i])
                v = _apply_unary(items[i][0], v)
            return v

        if tag == 'tern':
            for cond, qpos, then in node[1]:
                c = ev(cond)
                if not _is_bool(c):
                    raise ExprError('type', qpos)
                if c:
                    return ev(then)
            return ev(node[2])

        if tag == 'call':
            name = node[1]
            pos = node[2]
            args = node[3]
            if name == 'abs':
                if len(args) != 1:
                    raise ExprError('arity', pos)
            elif name == 'min' or name == 'max':
                if len(args) < 1:
                    raise ExprError('arity', pos)
            else:
                raise ExprError('name', pos)
            vals = [ev(a) for a in args]
            for v in vals:
                if not _is_int(v):
                    raise ExprError('type', pos)
            if name == 'abs':
                return abs(vals[0])
            if name == 'min':
                return min(vals)
            return max(vals)

        raise ExprError('syntax', 0)  # unreachable

    return ev


def evaluate(src, env):
    if sys.getrecursionlimit() < 10000:
        sys.setrecursionlimit(10000)
    toks = _tokenize(src)
    tree = _Parser(toks).parse()
    return _make_evaluator(env)(tree)
